/**
 * The complete function catalogue: every worksheet function this app can
 * calculate, grouped the way Excel's "Insert Function" dialog groups them, with
 * a one-line Hindi + English explanation and an example students can paste.
 *
 * Kept as data so the Formulas page, the ⌨ autocomplete and the in-cell help
 * popup all read from one list — and so `hasFunction()` in the engine can be
 * cross-checked against it by a test.
 */
export interface CatalogEntry {
  name: string;
  cat: CatalogCat;
  /** Short English purpose. */
  en: string;
  /** Hinglish/Hindi purpose. */
  hi: string;
  syntax: string;
  example: string;
  /** True for functions that need Microsoft 365 / a paid plan in real Excel. */
  m365?: boolean;
  /** True when the browser cannot honour it (documented limitation). */
  online?: boolean;
}

export type CatalogCat =
  | "Math & Trig"
  | "Statistical"
  | "Logical"
  | "Text"
  | "Date & Time"
  | "Lookup & Reference"
  | "Financial"
  | "Information"
  | "Engineering"
  | "Database"
  | "Dynamic Array"
  | "Web";

export const CATALOG_CATS: CatalogCat[] = [
  "Math & Trig",
  "Statistical",
  "Logical",
  "Text",
  "Date & Time",
  "Lookup & Reference",
  "Financial",
  "Information",
  "Engineering",
  "Database",
  "Dynamic Array",
  "Web",
];

const e = (
  name: string,
  cat: CatalogCat,
  syntax: string,
  en: string,
  hi: string,
  example: string,
  m365 = false,
): CatalogEntry => ({ name, cat, syntax, en, hi, example, m365 });

