/** Deduplicated list (some functions belong to two teaching categories). */
export const CATALOG_BY_NAME: Record<string, CatalogEntry> = (() => {
  const map: Record<string, CatalogEntry> = {};
  FORMULA_CATALOG.forEach((entry) => {
    if (!map[entry.name]) map[entry.name] = entry;
  });
  return map;
})();

export const CATALOG_NAMES: string[] = Object.keys(CATALOG_BY_NAME).sort();

/** The headline count shown in the UI. */
export const CATALOG_COUNT = CATALOG_NAMES.length;
export const M365_COUNT = Object.values(CATALOG_BY_NAME).filter((c) => c.m365).length;
